// One restaurant per execution (callers run this workflow once per item).
// Picks the branch by parser_name; manual / weekend / unknown sources finish here without fetching.
const src = $input.first().json;
const parserName = String(src.parser_name || src.parserName || 'manual');
const menuDate = String(src.menu_date || src.menuDate || '');
let parserConfig = src.parser_config || src.parserConfig || {};
if (typeof parserConfig === 'string') {
  try { parserConfig = JSON.parse(parserConfig || '{}'); } catch { parserConfig = {}; }
}
const hasWeekendMenu = src.has_weekend_menu === true || src.has_weekend_menu === 't' || src.has_weekend_menu === 'true';
const ROUTES = { woocommerce_category: 'html', amelia: 'html', sme_restauracie: 'html', zark_pdf: 'zark_pdf', ai_extract: 'ai_extract' };

const meta = {
  sourceId: String(src.source_id || src.sourceId || ''),
  sourceName: String(src.source_name || src.sourceName || src.source_id || ''),
  sourceType: String(src.source_type || src.sourceType || ''),
  sourceUrl: String(src.source_url || src.sourceUrl || ''),
  parserName,
  parser: parserName,
  parserConfig,
  hasWeekendMenu,
  menuDate,
  runId: String(src.run_id || src.runId || `${menuDate}-${Math.random().toString(36).slice(2, 10)}`),
  timeoutMs: Number(src.timeoutMs || 15000),
  maxItems: Number(src.maxItems || 100),
  discoveryUrl: parserConfig.discoveryUrl || (parserName === 'zark_pdf' ? 'https://zark.eatbu.com/?lang=sk' : null),
};
meta.run_id = meta.runId;

const day = new Date(`${menuDate}T12:00:00Z`);
const finish = (status, errorCode, errorMessage) => [{
  json: { ...meta, route: 'done', ok: status === 'skipped', status, stage: 'plan', errorCode, errorMessage, itemCount: 0, menuItems: [] },
}];

if (!/^\d{4}-\d{2}-\d{2}$/.test(menuDate) || Number.isNaN(day.getTime())) return finish('failed', 'INVALID_MENU_DATE', `Neplatný dátum menu: ${menuDate}`);
if (!meta.sourceId) return finish('failed', 'MISSING_SOURCE_ID', 'Chýba source_id reštaurácie.');
if (parserName === 'manual') return finish('skipped', 'MANUAL_SOURCE', 'Jedlá sa zadávajú ručne v admine.');
if (!ROUTES[parserName]) return finish('failed', 'UNKNOWN_PARSER', `Neznámy typ parsera: ${parserName}`);
if (!/^https?:\/\//i.test(meta.discoveryUrl || meta.sourceUrl)) return finish('failed', 'MISSING_URL', 'Reštaurácia nemá URL stránky s menu.');
if ([0, 6].includes(day.getUTCDay()) && !hasWeekendMenu) return finish('skipped', 'WEEKEND_NO_MENU', `Cez víkend (${menuDate}) sa menu neočakáva.`);

return [{ json: { ...meta, route: ROUTES[parserName] } }];

// HTML parsers, chosen by parser_name. Input: the fetched page (HTTP node, text response).
// Output: one result per restaurant in the shape the import audit expects.
const meta = $('Code - Plan').first().json;
const response = $input.first().json;

function decodeEntities(s) {
  return String(s || '')
    .replace(/&nbsp;|&#160;| /g, ' ')
    .replace(/&#8211;|&ndash;|&#8212;|&mdash;/g, '–')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#039;|&apos;/g, "'")
    .replace(/&euro;/g, '€')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
    .trim();
}

function cleanText(s) {
  return decodeEntities(s)
    .replace(/\s+/g, ' ')
    .replace(/\bPridať do košíka\b/gi, '')
    .replace(/\bKúpiť\b/gi, '')
    .replace(/\bSelect options\b/gi, '')
    .replace(/\bAdd to cart\b/gi, '')
    .trim();
}

function htmlToLines(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<br\s*\/?\s*>/gi, '\n')
    .replace(/<\/\s*(h\d|p|li|div|article|section|span|a|strong|em|ul|ol|td|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .split(/\n+/)
    .map(cleanText)
    .filter(Boolean);
}

function hashString(s) {
  let h = 2166136261;
  for (const ch of String(s)) {
    h ^= ch.charCodeAt(0);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16);
}

function toPrice(value) {
  const m = String(value || '').replace(/ /g, ' ').match(/([0-9]+)\s*[,.]\s*([0-9]{2})/);
  return m ? Number(`${m[1]}.${m[2]}`) : null;
}

function extractAllergens(raw) {
  const out = new Set();
  const parens = String(raw || '').match(/\(([^)]*\d[^)]*)\)/g) || [];
  for (const p of parens) for (const n of p.match(/\b\d{1,2}\b/g) || []) out.add(n);
  const explicit = String(raw || '').match(/alerg[eé]ny:?\s*((?:\d{1,2}\s*,?\s*)+)/i);
  if (explicit) for (const n of explicit[1].match(/\b\d{1,2}\b/g) || []) out.add(n);
  return [...out];
}

function isNoise(line) {
  const l = cleanText(line);
  if (!l) return true;
  if (/^(Domov|Menu|Ponuka|Denné menu|Polievky|Pizza|Nápoje|Dezerty|Kontakt|Košík|Pokladňa|Môj účet|Prihlásenie|Registrovať sa|Zobrazené všetky položky|Načítavanie\.\.\.|Created by)$/i.test(l)) return true;
  if (/^(Pridať do košíka|Kúpiť|Select options|Add to cart|Tlačiť menu|Zoznam alergénov|Jedálny lístok)$/i.test(l)) return true;
  if (/^Showing \d+ to \d+ of \d+/i.test(l)) return true;
  if (/cookie|súhlas|ochrana osobných údajov|technické uloženie|marketing|štatistiky/i.test(l)) return true;
  return false;
}

// Common item shape written to lunch_menu_items
function makeItem(item) {
  const title = cleanText(item.title);
  const price = typeof item.price === 'number' ? item.price : toPrice(item.price);
  if (!title || title.length < 3 || price === null || Number.isNaN(price)) return null;
  if (/košíka|select options|kúpiť|showing|cookie/i.test(title)) return null;
  const menuCode = item.menu_code || null;
  const identity = `${meta.sourceId}|${meta.menuDate}|${menuCode || ''}|${title}|${price}`;
  return {
    source_id: meta.sourceId,
    source_name: meta.sourceName,
    source_type: meta.sourceType,
    source_url: meta.sourceUrl,
    menu_date: meta.menuDate,
    item_uid: `${meta.sourceId}-${meta.menuDate}-${hashString(identity)}`,
    menu_code: menuCode,
    category: item.category || 'main',
    title,
    description: cleanText(item.description || ''),
    price_eur: price,
    currency: 'EUR',
    allergens: item.allergens || extractAllergens(item.raw || ''),
    raw_text: cleanText(item.raw || `${title} ${price} €`),
    parsed_at: new Date().toISOString(),
    run_id: meta.runId,
  };
}

// ---------- woocommerce_category (e.g. BelaVery): "01 – Title ... 7,90 €" ----------
function parseWoocommerce(html) {
  const lines = htmlToLines(html).filter((l) => !isNoise(l));
  const items = [];
  const candidates = [];
  for (let i = 0; i < lines.length; i++) {
    const titleMatch = lines[i].match(/^\s*(\d{1,2})\s*[–—-]\s*(.+)$/);
    if (!titleMatch) continue;
    let titleLine = titleMatch[2];
    let price = toPrice(titleLine);
    const desc = [];
    if (price !== null) {
      titleLine = cleanText(titleLine.replace(/\s*[0-9]+\s*[,.]\s*[0-9]{2}\s*€?.*$/i, ''));
    } else {
      for (let j = i + 1; j < Math.min(lines.length, i + 12); j++) {
        if (/^\s*\d{1,2}\s*[–—-]\s*/.test(lines[j])) break;
        const p = toPrice(lines[j]);
        if (p !== null) { price = p; break; }
        if (!isNoise(lines[j])) desc.push(lines[j]);
      }
    }
    candidates.push({ line: lines[i], titleLine, price });
    const item = makeItem({ menu_code: titleMatch[1].padStart(2, '0'), title: titleLine, description: desc.join(' '), price, raw: `${lines[i]} ${desc.join(' ')}` });
    if (item) items.push(item);
  }
  return { items, lines, candidates };
}

// ---------- amelia: weekly page with day blocks, weekly specials and a weekend menu ----------
const SK_DAYS = ['nedeľa', 'pondelok', 'utorok', 'streda', 'štvrtok', 'piatok', 'sobota'];
const EN_DAYS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];

function skDate(iso) {
  const [y, m, d] = iso.split('-').map(Number);
  return { y, m, d, text: `${d}.${m}.${y}` };
}
function dateOnLine(line) {
  const m = line.match(/^(\d{1,2})\.\s*(\d{1,2})\.\s*(\d{4})$/);
  return m ? `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}` : null;
}
const isDayName = (line) => SK_DAYS.includes(line.toLowerCase());
const isWeightLine = (line) => /^\d+(?:[.,]\d+)?\s*(?:g|kg|l|ml)$/i.test(line) || /^\d+g\/\d+g$/i.test(line);
const isPriceLine = (line) => /^\d+\s*[,.]\s*\d{2}\s*€$/.test(line);

// Items in a block: [code "1."] [weight] title… [category] [Alergény: …] price
function ameliaItems(block, description) {
  const items = [];
  let current = null;
  const start = () => (current ||= { titleParts: [], raw: [] });
  for (const line of block) {
    if (/^\d{1,2}\.$/.test(line)) { start().code = line.replace('.', '').padStart(2, '0'); continue; }
    if (isWeightLine(line)) {
      // A second weight inside one priced item = combo (e.g. soup + main for one price)
      if (current?.titleParts.length) current.titleParts.push('+');
      start().weight ||= line;
      current.raw.push(line);
      continue;
    }
    if (/^polievka$/i.test(line)) { start().category = 'soup'; continue; }
    if (/^hlavné jedlo$/i.test(line)) { start().category = 'main'; continue; }
    if (/^alerg[eé]ny:/i.test(line)) { start().allergens = extractAllergens(line); current.raw.push(line); continue; }
    if (isPriceLine(line)) {
      if (current && current.titleParts.length) {
        const title = current.titleParts.join(' ').replace(/\s+\+\s+/g, ' + ');
        const isSoup = !description && (current.category === 'soup' || (!current.category && /polievka|vývar|krém/i.test(title) && /l$/i.test(current.weight || '')));
        const item = makeItem({
          menu_code: current.code || (isSoup ? 'P' : null),
          title,
          description: [current.weight, description].filter(Boolean).join(' · '),
          price: toPrice(line),
          category: isSoup ? 'soup' : description ? 'special' : current.category || 'main',
          allergens: current.allergens || extractAllergens(title),
          raw: [...current.raw, title, line].join(' '),
        });
        if (item) items.push(item);
      }
      current = null;
      continue;
    }
    start().titleParts.push(line);
    current.raw.push(line);
  }
  return items;
}

function parseAmelia(html) {
  const lines = htmlToLines(html);
  const target = meta.menuDate;
  const weekday = EN_DAYS[new Date(`${target}T12:00:00Z`).getUTCDay()];
  const endIdx = lines.findIndex((l) => /^Denné menu podávame/i.test(l));
  const end = endIdx >= 0 ? endIdx : lines.length;

  // Day blocks start with a weekday name followed by its date on the next line
  const dayStarts = [];
  for (let i = 0; i < end - 1; i++) if (isDayName(lines[i]) && dateOnLine(lines[i + 1])) dayStarts.push({ i, date: dateOnLine(lines[i + 1]) });

  const items = [];
  const dayStart = dayStarts.find((d) => d.date === target);
  let closed = false;
  if (dayStart) {
    const next = dayStarts.find((d) => d.i > dayStart.i);
    const block = lines.slice(dayStart.i + 2, next ? next.i : end);
    if (block.some((l) => /^zatvoren[ée]/i.test(l))) closed = true;
    else items.push(...ameliaItems(block, ''));
  }

  // The page covers one week ("Denné menu" 12.10. - 18.10.2026); specials only apply inside it
  const weekIdx = lines.findIndex((l, k) => /^\d{1,2}\.\d{1,2}\.$/.test(l) && lines[k + 1] === '-' && dateOnLine(lines[k + 2] || ''));
  let inWeek = true;
  if (weekIdx >= 0) {
    const weekEnd = dateOnLine(lines[weekIdx + 2]);
    const [sd, sm] = lines[weekIdx].split('.').map(Number);
    const weekStart = `${weekEnd.slice(0, 4)}-${String(sm).padStart(2, '0')}-${String(sd).padStart(2, '0')}`;
    inWeek = target >= (weekStart <= weekEnd ? weekStart : `${Number(weekEnd.slice(0, 4)) - 1}${weekStart.slice(4)}`) && target <= weekEnd;
  }

  // "Platné dni:" sections (weekly special, weekend menu) before the first day block
  const firstDay = dayStarts.length ? dayStarts[0].i : end;
  const sections = [];
  for (let i = 0; i < firstDay; i++) if (/^Platné dni:?$/i.test(lines[i])) sections.push(i);
  sections.forEach((i, n) => {
    const days = (lines[i + 1] || '').toLowerCase().split(/\s*,\s*/);
    if (!inWeek || !days.includes(weekday)) return;
    let j = i + 2;
    const from = dateOnLine(lines[j] || '');
    let to = null;
    if (from && lines[j + 1] === '-' && dateOnLine(lines[j + 2] || '')) { to = dateOnLine(lines[j + 2]); j += 3; }
    if (from && (target < from || target > (to || from))) return;
    // Section label is the line(s) just above "Platné dni:", e.g. "Týždenný špeciál" / "Víkendové menu"
    const label = lines[i - 1] || 'Špeciál';
    const stop = sections[n + 1] !== undefined ? sections[n + 1] - 2 : firstDay;
    items.push(...ameliaItems(lines.slice(j, stop), label));
  });

  if (closed && !items.length) {
    return { items, lines, skipped: true, errorCode: 'RESTAURANT_CLOSED', errorMessage: `Reštaurácia má ${skDate(target).text} zatvorené.` };
  }
  return { items, lines, candidates: { dayFound: Boolean(dayStart), sections: sections.length } };
}

// ---------- sme_restauracie: restauracie.sme.sk "denné menu" page ----------
function normalizeNoAccents(value) {
  return String(value || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}
function parseSme(html) {
  const lines = htmlToLines(html);
  if (lines.some((l) => /security verification|captcha/i.test(l))) {
    return { items: [], lines, errorCode: 'BLOCKED_BY_CAPTCHA', errorMessage: 'SME zobrazilo overenie (captcha) namiesto menu, automatické čítanie je zablokované.' };
  }
  const [y, m, d] = meta.menuDate.split('-');
  const variants = [`${d}.${m}.${y}`, `${Number(d)}.${Number(m)}.${y}`, `${Number(d)}. ${Number(m)}. ${y}`, `${d}.${m}.`, `${Number(d)}.${Number(m)}.`].map(normalizeNoAccents);
  const dayName = normalizeNoAccents(['nedela', 'pondelok', 'utorok', 'streda', 'stvrtok', 'piatok', 'sobota'][new Date(`${meta.menuDate}T12:00:00Z`).getUTCDay()]);
  const norm = lines.map(normalizeNoAccents);
  const anchor = norm.findIndex((l) => l.includes(dayName) || variants.some((v) => l.includes(v)) || /\bdnes\b/.test(l));
  const dayNames = ['pondelok', 'utorok', 'streda', 'stvrtok', 'piatok', 'sobota', 'nedela'];
  let block = lines;
  if (anchor >= 0) {
    let stop = Math.min(lines.length, anchor + 100);
    for (let i = anchor + 1; i < stop; i++) if (dayNames.some((n) => n !== dayName && norm[i].startsWith(n))) { stop = i; break; }
    block = lines.slice(anchor, stop);
  }
  const items = [];
  let counter = 1;
  for (const raw of block) {
    const line = raw.replace(/^[-–•]\s*/, '').trim();
    if (!/(\d{1,2})\s*[,.]\s*(\d{2})\s*(?:€|eur)/i.test(line)) continue;
    const title = line.replace(/(\d{1,2})\s*[,.]\s*(\d{2})\s*(?:€|eur)/ig, '').replace(/^\s*(?:menu\s*)?[0-9]{1,2}\s*[.)/:=-]\s*/i, '').trim();
    const code = (line.match(/^\s*(?:menu\s*)?([0-9]{1,2})\s*[.)/:=-]/i) || [])[1];
    let category = 'main';
    if (/polievka|vývar|vyvar|soup/i.test(title)) category = 'soup';
    const item = makeItem({ menu_code: (code || String(counter)).padStart(2, '0'), title, price: toPrice(line), category, raw: line });
    if (item) { items.push(item); counter++; }
  }
  return { items, lines, block };
}

const PARSERS = { woocommerce_category: parseWoocommerce, amelia: parseAmelia, sme_restauracie: parseSme };

function result(extra) {
  return {
    sourceId: meta.sourceId,
    sourceName: meta.sourceName,
    sourceType: meta.sourceType,
    sourceUrl: meta.sourceUrl,
    parser: meta.parserName,
    menuDate: meta.menuDate,
    runId: meta.runId,
    run_id: meta.runId,
    fetchedAt: new Date().toISOString(),
    ...extra,
  };
}

const html = typeof response.data === 'string' ? response.data
  : typeof response.body === 'string' ? response.body
  : Object.values(response).find((v) => typeof v === 'string' && v.length > 300) || '';

if (response.error || !html) {
  const message = String(response.error?.message || response.error || 'Prázdna odpoveď zo servera');
  const blocked = /\b403\b/.test(message);
  return [{ json: result({
    ok: false, status: 'failed', stage: 'fetch',
    errorCode: blocked ? 'BLOCKED_HTTP_403' : 'HTTP_FETCH_FAILED',
    errorMessage: (blocked ? 'Web vrátil 403 – pravdepodobne blokuje automatické čítanie (captcha/ochrana proti botom). ' : '') + message.slice(0, 500),
    itemCount: 0, menuItems: [],
  }) }];
}

const parse = PARSERS[meta.parserName];
if (!parse) {
  return [{ json: result({ ok: false, status: 'failed', stage: 'parse', errorCode: 'UNKNOWN_PARSER', errorMessage: `Neznámy HTML parser: ${meta.parserName}`, itemCount: 0, menuItems: [] }) }];
}

const parsed = parse(html);
const items = [...new Map(parsed.items.map((i) => [i.item_uid, i])).values()].slice(0, meta.maxItems || 100);
const ok = items.length > 0;
return [{
  json: result({
    ok: ok || Boolean(parsed.skipped),
    status: ok ? 'success' : parsed.skipped ? 'skipped' : 'failed',
    stage: 'parse',
    errorCode: ok ? null : parsed.errorCode || 'NO_MENU_ITEMS_PARSED',
    errorMessage: ok ? null : parsed.errorMessage || `Pre ${meta.sourceName} sa na ${meta.menuDate} nenašli žiadne jedlá.`,
    itemCount: items.length,
    menuItems: items,
    debugDayLines: (parsed.block || parsed.lines || []).slice(0, 120),
  }),
}];

// Fail closed: never fall back to last week's hardcoded PDF.
const meta = $('Code - Plan').first().json;
const response = $input.first().json;
if (Number(response.statusCode) !== 200) throw new Error('ZARK_DISCOVERY_HTTP_STATUS: ' + response.statusCode);
const html = response.body ?? response.data;
if (typeof html !== 'string' || !html.length || html.length > 2 * 1024 * 1024) throw new Error('ZARK_DISCOVERY_INVALID_HTML_SIZE');
const decoded = html.replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#(?:0*39|x0*27);/gi, "'")
 .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
 .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n,16)))
 .replace(/\\u002f/gi, '/').replace(/\\\//g, '/');
const found = [];
for (const m of decoded.matchAll(/(?:href|data-src|data-url|src)\s*=\s*["']([^"']+)["']/gi)) found.push(m[1]);
for (const m of decoded.matchAll(/(?:[a-z][a-z0-9+.-]*:)?\/\/[^\s"'<>\\]+/gi)) found.push(m[0]);
const urls = new Set();
for (let candidate of found) {
 try { candidate = decodeURIComponent(candidate.trim()); } catch { continue; }
 if (candidate.startsWith('//')) candidate = 'https:' + candidate;
 // Anchored allowlist: no credentials, ports, suffix hosts, alternate protocol or path traversal.
 const match = candidate.match(/^https:\/\/cdn\.website\.dish\.co(\/media\/[a-f0-9]{2}\/[a-f0-9]{2}\/\d+\/Tyzdenne-menu\.pdf)(?:\?[^\s"'<>#\\]*)?(?:#[^\s"'<>\\]*)?$/i);
 if (match) urls.add('https://cdn.website.dish.co' + match[1]);
}
if (urls.size !== 1) throw new Error(`ZARK_DISCOVERY_EXPECTED_ONE_PDF: found ${urls.size}; ${JSON.stringify([...urls])}`);
const pdfUrl = [...urls][0];
const resolvedAt = new Date().toISOString();
console.log(JSON.stringify({event:'zark_pdf_resolved',runId:meta.runId,pdfUrl,resolvedAt}));
return [{json:{...meta,sourceUrl:pdfUrl,pdfUrl,discoveryUrl:meta.discoveryUrl,resolvedAt,stage:'zark_discovery',status:'resolved'},pairedItem:{item:0}}];

const item = $input.first();
const meta = $('Code - ZARK Resolve PDF URL').first().json;
if (Number(item.json.statusCode) !== 200) throw new Error('ZARK_PDF_HTTP_STATUS: ' + item.json.statusCode);
const headers = item.json.headers || {};
const type = String(headers['content-type'] || headers['Content-Type'] || '').split(';')[0].trim().toLowerCase();
if (type !== 'application/pdf') throw new Error('ZARK_PDF_CONTENT_TYPE: ' + type);
const declared = Number(headers['content-length'] || headers['Content-Length'] || 0);
const maxBytes = 8 * 1024 * 1024;
if (declared > maxBytes) throw new Error('ZARK_PDF_TOO_LARGE');
if (!item.binary?.data) throw new Error('ZARK_PDF_BINARY_MISSING');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (buffer.length < 8 || buffer.length > maxBytes) throw new Error('ZARK_PDF_INVALID_SIZE: ' + buffer.length);
if (buffer.subarray(0,5).toString('ascii') !== '%PDF-') throw new Error('ZARK_PDF_INVALID_SIGNATURE');
console.log(JSON.stringify({event:'zark_pdf_validated',runId:meta.runId,pdfUrl:meta.pdfUrl,bytes:buffer.length,contentType:type}));
return [{json:{...meta,pdfBytes:buffer.length,contentType:type,stage:'zark_pdf_validated'},binary:item.binary,pairedItem:{item:0}}];

// Validate only the menu heading: never infer the week from HTTP Last-Modified or the URL.
const item = $input.first();
const meta = $('Code - ZARK Resolve PDF URL').first().json;
const fields = [item.json.text, item.json.data, item.json.content, item.json.extractedText, item.json.output];
const text = fields.find(s => typeof s === 'string' && /ZARK/i.test(s));
if (!text) throw new Error('ZARK_WEEK_TEXT_MISSING: PDF extractor returned no readable ZARK text');

// ZARK daily lunch is not expected on Saturday/Sunday; weekday freshness checks below remain unchanged.
const weekendRef = String(meta.menuDate || '');
const weekendDate = new Date(weekendRef + 'T12:00:00Z');
